from ui_incremental import *
record(P+'ViewModels/InventoryViewModel.cs','Stock overview/detail/physical count sheets/single count/waste money-sensitive UI.',[
('LoadAsync','Real stock overview+last60movements+selected detail; single busy guard, no cancellation, snapshots values from backend. Unknown value caveat and negative balance warning correctly avoid zero/moral accusation; NameOf/UnitOf linear lookup per60movements O(items*60).'),
('LoadDetailAsync','SelectedItem snapshot row but no generation/identity after await; old detail can publish under new/closed selection and set IsDetailLoading false while next read pending. Only reports_view allowed cost detail, inventory_manage without reports cannot open detail; intentional value gate but can still count/waste.'),
('MovementRow','Displays actual direction/quantity/value/cost provenance/reference/actor; unknown monetary value dash. Formats station-local timestamp instead of Cairo; presentation only.'),
('CountLine','Observed quantity nullable on invalid/blank, variance=typed minus cachedsystem, unchecked long difference/valuation; physical count difference based cached snapshot can age while sales continue. Per-line Changed calls parent counters; no durable row state itself.'),
('RebuildCountSheet','Copies only currently visible typed dictionary then rebuilds from filtered Items. Hiding shelfAforBthenbackA loses typedA because hidden rows no longer saved; contradicts keep figures intent. After Load refresh rebuild also recalculates baselines.'),
('SubmitCountSheetAsync','Direct per-line RecordCountAdjustment with deterministic sheet-item ID, no RetainedRequest or immutable whole-sheet capture; one approval shared all lines, backend token reuse needs handler check. First fail/unknown does not register persistent unknown; after summary Load refresh recomputes differences against latest balances and potentially changes retry payload for same IDs. Cancel/navigation allowed once IsBusy false. Successful lines and failures not atomically submitted, intentional partial batch must be explicit/recoverable.'),
('SubmitCountAsync','Single-item actual amount validates MilliUnits/reason, computes difference from snapshot, real approval, durable typed request; retry branch before CountTarget required. Native recovered modal not restored in constructor so actual retry button reachability unverified.'),
('SubmitWasteAsync','Typed waste positive quantity/reason, known type choice UI, real approval; durable request preserves quantity and ID, server returned nullable loss value accurately worded unknown. Close/open mutation guarded by CanEditAction; session pending initially only IsBusy change.'),
('ResolveApprovalAsync','Single actual approval endpoint, no forged client identity accepted. Business concurrency/transactions server owns. Number overflow risk on extreme inputs not runtime reproduced.')],
'Need filter-away/back count draft preservation; partial sheet commit/lost-response/reload/concurrent-sale immutable retry; count/waste reconstructed native recovery; detail A/B stale read and extreme valuation. No stock writes.',
'Durable exact per-line outcome journal/whole sheet coordinator, preserve hidden count inputs by item ID, compare authoritative current balance explicitly, version detail requests and safe bound arithmetic.')
record(P+'ViewModels/PurchasingViewModel.cs','Supplier directory, invoice receiving/payment/due dates and payable aging.',[
('LoadAsync','Real suppliers,purchases,active stock,optional overview currentcost then aging sequential. No request cancellation; errors can leave earlier sections updated and later stale. CanAddSupplier OR purchasing/suppliers permission; server final auth.'),
('LoadPayablesAsync','Failure silently retains old Aging/Payables or empty panel while other lists valid. Unlike comments safety wish, operator cannot distinguish unavailable aging from clean/no late invoices; source risk needs UI report unavailable state.'),
('SubmitDueDateAsync','Invariant yyyy-MM-dd or blank null, fresh Guid every submit; no durable outcome identity. Idempotent value setter, less duplicate-money risk, but can abandon uncertainty and overwrite newer date if retry stale.'),
('SubmitSupplierAsync','Mandatory name, real supplier approval if neither permission; typed durable request ID captured once, success reload. Pending request can retry without dialog but native recovery state IsSupplierOpen false not hydrated.'),
('PurchaseLineEntry','Selected item lookup prior unit cost; change text notifies10xwarning. Multiplying longprevious/typed by10unchecked can overflow extreme valid money values and suppress warning. Display help actual source cost, not invented.'),
('SubmitReceiveAsync','Pending exact DTO first, fresh lines parse positive milli quantity/unitcost, skips item-null rows even if user typed amount, requires nonempty. Suspicious cost acknowledgement not reset when line changes after acknowledged, so later big change may remain implicitly acknowledged. Valid optional due date; credit sends0paid. Approval captured server, immutable ReceivePurchaseRequest sent once per modal and retained before network.'),
('SubmitPayAsync','Pending exact typedPayPurchase first; positive amount, no local cap vs shown remaining (server must enforce). Stable per-modal ID and actual chosen method/approval; result success amount from request not server DTO, contract expected same paid amount. Server multi-row ledger/treasury transaction separate.'),
('CompleteReceiveAsync','Authoritative total in note; closes and reloads. Supplier/receive/pay all3helpers durable but initial session pending only busy change and dialogs not reconstructed, a broad recovery UI gap requiring native button visibility check. All PIN fields remain until next open rather than clear on close.')],
'Need real-VM reconstructed supplier/receive/pay retry UI, cost-warning acknowledgment reset, empty-item typed row warning, stale aging error, partial read refresh and payment cap contracts. No supplier/invoice/payment records written.',
'Make stale aging explicitly unavailable, reset acknowledgement on changed suspicious input, hydrate original pending action visible and protected; retain backend atomic receiving/settlement.')
record(P+'ViewModels/DailySummaryViewModel.cs','Actual selected/latest business-day printable-style daily summary data.',[
('LoadAsync','Settings optional then current day; any current failure falls back history, not only404. Transient current error may show latest historical day while user expects today; summary displays actual BusinessDate so explicit date helps. Empty history correct no day; summary failure LoadError.'),
('FormatArabicLongDate','Invariant ISO input parsed DateOnly, ar-EG long date; parse failure preserves raw rather than fabricate date.'),
('NetShiftDifferencePiastres','Overage-shortage, advances+withdrawals grouped true server amounts; nullSummary0but view HasSummary gates actual sheet. No direct printing command; source explicitly management print pipeline absent, cannot claim printable/exported report working.')],
'Need current non404failure fallback message test and actual date label, no-day/unknown vszero. No print jobs created.',
'Distinguish current-day lookup failure from genuinely closed/no day before history fallback; report no management paper pipeline honestly.')
record(P+'ViewModels/DailyStatementViewModel.cs','Owner day-specific consolidated statement and expense reprint.',[
('DailyStatementViewModel','Captures Cairo today once at construction; long-open page crossing midnight Today/Yesterday buttons still olddate. No timer rollover, legitimate static snapshot but label can mislead.'),
('LoadAsync','Selected-date snapshot checked after read, queues reload if changed; correct stale read prevention. On failure Statement=null but old ExpenseLines/Shifts/etc collections not cleared, paired XAML must gate on Statement/error to avoid stale section display.'),
('ApplyProductFilter','Persists CategoryFilter across dates; new date category absent leaves no rows until choose all, could look no sales. ProductHourly groups by ProductName not stable ProductId, merges distinct products sharing name; actual DTO onlyname maybe schema limitation.'),
('ReprintExpenseAsync','Real marked expense voucher document print job with new Guid each intended press; same-process busy guard, no durable ambiguous print replay. Does not mutate expense/treasury; says queued paper not confirmed. No printing executed.'),
('ProductHourRow','Plain immutable row formats hour and quantities; cost/report values from actual server statement, no mock data.')],
'Need midnight rollover, date change category filter, error clears stale sections and ambiguous reprint identity tests; no actual receipt rendered.',
'Reset invalid filter on new day, bind all sections to valid matching statement, show businessdate truth and durable reprint semantics.')
record(P+'ViewModels/WasteViewModel.cs','Per-day waste/spoilage/breakage summary and movement list.',[
('LoadAsync','Summary requested with BusinessDate, but movements fetch last200global and filter only Type, never businessdate. Thus date-specific totals paired with arbitrary all-date movement list; relevant rows can be omitted due global cap. Source-confirmed misleading report, backend endpoint date query not passed.'),
('PreviousDay','Changes date then calls Load; NextDay same. If existing read busy, LoadAsync returns and no queued reload/version. Slow old-date response assigned under new date, source stale-read defect.'),
('HasNoLoss','NullSummarytreated0only when noerror/notloading. ByType actual server values, labels preserve3loss classes and unknownvalue handling in XAML not this VM. Constructor Cairo current date correct.')],
'Need delayed date flip and multi-date globalmovement fixture: all displayed rows must match selected Cairo business range and full relevant result. No waste writes (read-only screen).',
'Query loss movements by exact businessday/range with paging, coalesce/version date changes like Audit/Attendance. Do not infer displayed list explains total until verified.')
record(P+'ViewModels/DeliveryViewModel.Statistics.cs','Driver performance period/date query and display.',[
('ResolveStatsRange','BusinessClock.Today Cairo, last7/month/customdates sorted, translates inclusive selected dates into exact UTC start/end using BusinessClock. API escapes offsets, no accidental+tospace.'),
('LoadDriverStatisticsAsync','Version on each request, checks before publish/finally; good stale period response guard. Need base CloseAccount to increment version to invalidate closed-driver response (not yet reviewed); no cancellation network.'),
('AverageDeliveryMinutesDisplay','Nullunknown dash, does not invent instant0; explicit last order/settlement Cairo formatting. HasStatistics based DTO presence, no financial calculation.'),
('ReloadStatisticsForCurrentDriver','Picker changes and period set trigger actual selecteddriver query; possible burst queries but only latest version published. No database writes/settlement here.')],
'Need close/account switch invalidates version and exact Cairo DST dateboundaries; no endpoint requests executed.',
'Keep version guard and add task cancellation; validate base lifecycle clears stale statistics on close.')
